const prev = $('Claim check and build review form').first().json;
const meta = $('Resolve Substack API URL').first().json;
const review = $json;
const decision = review['Editorial decision'];
const results = prev.drafts.map(d => {
  const key = Object.keys(review).find(k => k.startsWith(d.format + ' ['));
  const finalText = key && review[key] ? String(review[key]) : d.text;
  const norm = x => String(x).split(String.fromCharCode(13)).join('').split(String.fromCharCode(10)).map(l => l.trimEnd()).join(' ').trim();
  const edited = norm(finalText) !== norm(d.text);
  const r = checkText(finalText, prev.doc.passages);
  const status = decision.startsWith('Send') ? 'Sent back' : (r.issues.length ? 'Blocked: claim check failed' : 'Approved');
  return { format: d.format, sources: d.sources, edited, numbersChecked: r.numbersChecked, issues: r.issues, status, text: finalText };
});
const runAt = new Date().toISOString();
const counts = { approved: results.filter(r => r.status === 'Approved').length, blocked: results.filter(r => r.status.startsWith('Blocked')).length, edited: results.filter(r => r.edited).length };
let md = '# RepurposeIQ run\n\nSource: ' + prev.doc.title + '\n' + prev.doc.url + '\n\nRun: ' + runAt + ' | Execution ' + $execution.id + ' | Editor: ' + meta.editor + ' | Decision: ' + decision + '\n\nApproved ' + counts.approved + ', blocked ' + counts.blocked + ', edited ' + counts.edited + ' of ' + results.length + '\n';
for (const r of results) md += '\n## ' + r.format + ' (' + r.status + ')\nSources: ' + r.sources.join(', ') + (r.issues.length ? '\nIssues: ' + r.issues.join('; ') : '') + '\n\n' + r.text + '\n';
md += '\n## Review notes\n' + (review['Review notes'] || 'None') + '\n';
const summaryText = 'Approved ' + counts.approved + ' of ' + results.length + ' drafts. ' + (counts.blocked ? counts.blocked + ' blocked by the claim check after editing. ' : '') + 'Saved as run-' + $execution.id + '.';
return [{ json: { runAt, execution: $execution.id, source: { title: prev.doc.title, url: prev.doc.url }, editor: meta.editor, decision, notes: review['Review notes'] || '', counts, results, markdown: md, summaryText } }];
